import React, { useState, useEffect } from 'react';

const Gallery = () => {
  const [galleryData, setGalleryData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedImage, setSelectedImage] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbxdTSFAmQoaJWhkay-4V5BbqyhLcKDGQwf-1rFVzAbRKISfT-z9Aoowu6meXoiPpx8f/exec';

  const fetchGalleryData = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status}`);
      }
      const result = await response.json();
      console.log('=== API RESPONSE ===');
      console.log('Full API result:', result);
      
      if (result.success) {
        console.log('=== DATA STRUCTURE ===');
        console.log('Raw data array:', result.data);
        
        // Check the first few items to understand the structure
        if (result.data && result.data.length > 0) {
          console.log('First item in data:', result.data[0]);
          console.log('Type of first item:', typeof result.data[0]);
          if (Array.isArray(result.data[0])) {
            console.log('First item is array, length:', result.data[0].length);
            console.log('First item contents:', result.data[0]);
          }
        }
        
        const transformedData = result.data.map((item, index) => {
          // Handle different possible data structures
          let imageNo, imageUrl;
          
          if (Array.isArray(item)) {
            imageNo = item[0] || index + 1;
            imageUrl = item[1] || '';
            console.log(`Item ${index} (array):`, { array: item, imageNo, imageUrl });
          } else if (typeof item === 'object' && item !== null) {
            imageNo = item.imageNo || item[0] || index + 1;
            imageUrl = item.imageUrl || item[1] || '';
            console.log(`Item ${index} (object):`, { object: item, imageNo, imageUrl });
          } else {
            imageNo = index + 1;
            imageUrl = item || '';
            console.log(`Item ${index} (other):`, { value: item, imageNo, imageUrl });
          }
          
          return { imageNo, imageUrl };
        }).filter(item => item.imageUrl && item.imageUrl.trim() !== '');
        
        console.log('=== FINAL TRANSFORMED DATA ===');
        console.log('Transformed data:', transformedData);
        setGalleryData(transformedData);
      } else {
        throw new Error(result.error || 'Failed to fetch data');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchGalleryData();
  }, []);

  // CORRECTED Google Drive URL handling with detailed logging
  const getThumbnailUrl = (driveUrl) => {
    console.log('=== PROCESSING DRIVE URL ===');
    console.log('Input URL:', driveUrl);
    
    if (!driveUrl) {
      console.log('❌ No URL provided');
      return '';
    }
    
    // Check if it's a Google Drive URL
    const isDriveUrl = driveUrl.includes('drive.google.com');
    console.log('Is Google Drive URL:', isDriveUrl);
    
    if (!isDriveUrl) {
      console.log('ℹ️ Not a Google Drive URL, returning original');
      return driveUrl;
    }
    
    // Try multiple patterns to extract file ID
    console.log('=== EXTRACTING FILE ID ===');
    
    // Pattern 1: /file/d/FILE_ID/ (for your URL format)
    const pattern1 = driveUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    console.log('Pattern 1 (/file/d/):', pattern1);
    
    // Pattern 2: /d/FILE_ID/ (alternative format)
    const pattern2 = driveUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
    console.log('Pattern 2 (/d/):', pattern2);
    
    // Pattern 3: id=FILE_ID
    const pattern3 = driveUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
    console.log('Pattern 3 (id=):', pattern3);
    
    // Pattern 4: /uc?id=FILE_ID
    const pattern4 = driveUrl.match(/uc\?id=([a-zA-Z0-9_-]+)/);
    console.log('Pattern 4 (uc?id=):', pattern4);
    
    let fileId = null;
    
    if (pattern1 && pattern1[1]) {
      fileId = pattern1[1];
      console.log('✅ Using Pattern 1, File ID:', fileId);
    } else if (pattern2 && pattern2[1]) {
      fileId = pattern2[1];
      console.log('✅ Using Pattern 2, File ID:', fileId);
    } else if (pattern3 && pattern3[1]) {
      fileId = pattern3[1];
      console.log('✅ Using Pattern 3, File ID:', fileId);
    } else if (pattern4 && pattern4[1]) {
      fileId = pattern4[1];
      console.log('✅ Using Pattern 4, File ID:', fileId);
    } else {
      console.log('❌ No file ID found in URL');
      return driveUrl;
    }
    
    // Generate thumbnail URL
    const thumbnailUrl = `https://drive.google.com/thumbnail?id=${fileId}&sz=w400`;
    console.log('=== GENERATED THUMBNAIL URL ===');
    console.log('Thumbnail URL:', thumbnailUrl);
    
    return thumbnailUrl;
  };

  const getFullSizeUrl = (driveUrl) => {
    console.log('=== GENERATING FULL SIZE URL ===');
    console.log('Input URL:', driveUrl);
    
    if (!driveUrl) return '';
    
    if (!driveUrl.includes('drive.google.com')) {
      return driveUrl;
    }
    
    // Extract file ID using the same patterns
    const pattern1 = driveUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    const pattern2 = driveUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
    const pattern3 = driveUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
    
    let fileId = null;
    
    if (pattern1 && pattern1[1]) {
      fileId = pattern1[1];
    } else if (pattern2 && pattern2[1]) {
      fileId = pattern2[1];
    } else if (pattern3 && pattern3[1]) {
      fileId = pattern3[1];
    }
    
    if (fileId) {
      const fullSizeUrl = `https://drive.google.com/uc?export=view&id=${fileId}`;
      console.log('Full size URL:', fullSizeUrl);
      return fullSizeUrl;
    }
    
    console.log('❌ Could not generate full size URL, returning original');
    return driveUrl;
  };

  const isGoogleDriveUrl = (url) => {
    return url && url.includes('drive.google.com');
  };

  const openModal = (item) => {
    console.log('=== OPENING MODAL ===');
    console.log('Selected item:', item);
    
    const imageUrl = item.imageUrl;
    const thumbnailUrl = isGoogleDriveUrl(imageUrl) ? getThumbnailUrl(imageUrl) : imageUrl;
    const fullSizeUrl = isGoogleDriveUrl(imageUrl) ? getFullSizeUrl(imageUrl) : imageUrl;
    
    console.log('Modal URLs:', { original: imageUrl, thumbnail: thumbnailUrl, fullSize: fullSizeUrl });
    
    setSelectedImage({
      ...item,
      thumbnailUrl,
      fullSizeUrl
    });
    setIsModalOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedImage(null);
    document.body.style.overflow = 'unset';
  };

  useEffect(() => {
    const handleEscape = (e) => {
      if (e.key === 'Escape' && isModalOpen) {
        closeModal();
      }
    };

    window.addEventListener('keydown', handleEscape);
    return () => window.removeEventListener('keydown', handleEscape);
  }, [isModalOpen]);

  // Test the URL parsing with your specific URL
  useEffect(() => {
    if (galleryData.length > 0) {
      console.log('=== TESTING URL PARSING ===');
      const testUrl = 'https://drive.google.com/file/d/1pYzaHzZ6CqhyNPe8tsLh6SHSbZQSc3H7/view?usp=sharing';
      console.log('Test URL:', testUrl);
      getThumbnailUrl(testUrl);
    }
  }, [galleryData]);

  if (loading) {
    return (
      <div style={{ padding: '2rem', textAlign: 'center', fontFamily: 'Arial, sans-serif' }}>
        <h2>Loading photos...</h2>
        <div style={{ 
          display: 'inline-block',
          width: '50px',
          height: '50px',
          border: '3px solid #f3f3f3',
          borderTop: '3px solid #3498db',
          borderRadius: '50%',
          animation: 'spin 1s linear infinite'
        }}></div>
        <style>{`@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}</style>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ padding: '2rem', textAlign: 'center', fontFamily: 'Arial, sans-serif' }}>
        <h2 style={{ color: '#e74c3c' }}>Error Loading Photos</h2>
        <p style={{ color: '#666', marginBottom: '1rem' }}>{error}</p>
        <button 
          onClick={fetchGalleryData}
          style={{
            padding: '0.5rem 1rem',
            backgroundColor: '#3498db',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          Try Again
        </button>
      </div>
    );
  }

  return (
    <>
      <div style={{ padding: '2rem', fontFamily: 'Arial, sans-serif', maxWidth: '1200px', margin: '0 auto' }}>
        <h1 style={{ textAlign: 'center', marginBottom: '1rem' }}>Photo Gallery</h1>
        <p style={{ textAlign: 'center', color: '#666', marginBottom: '2rem' }}>
          {galleryData.length} {galleryData.length === 1 ? 'photo' : 'photos'}
        </p>
        
        {galleryData.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '2rem' }}>
            <p>No photos found.</p>
            <button 
              onClick={fetchGalleryData}
              style={{
                padding: '0.5rem 1rem',
                backgroundColor: '#3498db',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                marginTop: '1rem'
              }}
            >
              Refresh
            </button>
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '1rem' }}>
            {galleryData.map((item, idx) => {
              console.log(`=== RENDERING IMAGE ${idx} ===`);
              console.log('Item data:', item);
              
              const thumbnailUrl = getThumbnailUrl(item.imageUrl);
              console.log('Final thumbnail URL for rendering:', thumbnailUrl);
              
              return (
                <div 
                  key={idx} 
                  style={{ 
                    cursor: 'pointer',
                    borderRadius: '8px',
                    overflow: 'hidden',
                    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                    transition: 'transform 0.2s',
                    backgroundColor: 'white'
                  }}
                  onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.02)'}
                  onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}
                  onClick={() => openModal(item)}
                >
                  <div style={{ position: 'relative', paddingBottom: '75%', overflow: 'hidden' }}>
                    <img
                      src={thumbnailUrl}
                      alt={`Photo ${item.imageNo}`}
                      style={{ 
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: '100%',
                        objectFit: 'cover'
                      }}
                      onLoad={() => console.log(`✅ Image ${idx} loaded successfully:`, thumbnailUrl)}
                      onError={(e) => {
                        console.error(`❌ Image ${idx} failed to load:`, thumbnailUrl);
                        console.error('Error event:', e);
                        e.target.style.backgroundColor = '#f0f0f0';
                        e.target.alt = `Failed to load photo ${item.imageNo}`;
                      }}
                    />
                  </div>
                  <div style={{ padding: '0.75rem' }}>
                    <p style={{ margin: 0, textAlign: 'center', fontWeight: 'bold', color: '#333' }}>
                      Photo #{item.imageNo}
                    </p>
                    <p style={{ margin: 0, textAlign: 'center', fontSize: '12px', color: '#666', marginTop: '4px' }}>
                      {item.imageUrl ? 'Click to view' : 'No URL'}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {isModalOpen && selectedImage && (
        <div
          onClick={closeModal}
          style={{
            position: 'fixed',
            inset: 0,
            backgroundColor: 'rgba(0,0,0,0.85)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            padding: '1rem',
            zIndex: 1000
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{ 
              maxWidth: '90vw', 
              maxHeight: '90vh', 
              position: 'relative',
              backgroundColor: 'white',
              borderRadius: '8px',
              padding: '1rem'
            }}
          >
            <button
              onClick={closeModal}
              style={{
                position: 'absolute',
                top: '-40px',
                right: '0',
                backgroundColor: 'white',
                color: '#333',
                border: 'none',
                borderRadius: '4px',
                padding: '0.5rem 1rem',
                cursor: 'pointer',
                fontWeight: 'bold'
              }}
            >
              Close
            </button>
            <img
              src={selectedImage.fullSizeUrl}
              alt={`Photo ${selectedImage.imageNo}`}
              style={{ 
                maxWidth: '100%', 
                maxHeight: '80vh', 
                display: 'block',
                borderRadius: '4px'
              }}
              onLoad={() => console.log('✅ Modal image loaded successfully')}
              onError={(e) => console.error('❌ Modal image failed to load')}
            />
            <p style={{ textAlign: 'center', marginTop: '1rem', fontWeight: 'bold' }}>
              Photo #{selectedImage.imageNo}
            </p>
          </div>
        </div>
      )}
    </>
  );
};

export default Gallery;
